const inputDocs = $input.first().json.contents; // Assumendo che il JSON sia nel primo item
let finalBinary = {};
let promptManifest = "";
let testiDigeriti = [];

let imageCounter = 0;

inputDocs.forEach((doc, docIndex) => {
    const docName = doc.filename || `Documento_${docIndex + 1}`;

    // 1. Salviamo testo e firmatari
    testiDigeriti.push({
        document: docName,
        signers: doc.signers || [],
        text: doc.text || ""
    });

    // 2. Prepariamo le immagini e aggiorniamo il manifesto
    if (doc.images && Array.isArray(doc.images)) {
        let docImageIndexes = [];

        doc.images.forEach((imgObj) => {
            // Rimuove l'header base64 se presente
            const cleanBase64 = imgObj.content.replace(/^data:image\/\w+;base64,/, "");
            let ext = imgObj.ext ? imgObj.ext.toLowerCase() : 'jpeg';
            if (ext === 'jpg') ext = 'jpeg';

            // Format: img_001, img_002... (Lo zero-pad garantisce l'ordine alfabetico in n8n)
            const binaryKey = `img_${String(imageCounter).padStart(3, '0')}`;

            finalBinary[binaryKey] = {
                data: cleanBase64,
                mimeType: `image/${ext}`,
                fileName: `${docName}_pag_${docImageIndexes.length + 1}.${ext}`
            };

            docImageIndexes.push(imageCounter + 1); // Indice umano (1-based)
            imageCounter++;
        });

        if (docImageIndexes.length > 0) {
            promptManifest += `- ${docName}: Immagini dalla n. ${docImageIndexes[0]} alla n. ${docImageIndexes[docImageIndexes.length - 1]}\n`;
        } else {
            promptManifest += `- ${docName}: Nessuna immagine allegata.\n`;
        }
    }
});

// Restituiamo UN SOLO ITEM a n8n, contenente tutto
return [{
    json: {
        documenti: testiDigeriti,
        manifesto_immagini: promptManifest,
        totale_immagini: imageCounter
    },
    binary: finalBinary
}];

let output_combiner = []

for (const item of $input.all()) {
  output_combiner.push(item);
}

return output_combiner;

// Recuperiamo la stringa prodotta dall'AI (adattare il nome del campo se diverso)
const rawOutput = $input.first().json.output; 

if (!rawOutput) {
    throw new Error("Nessun output ricevuto dal nodo precedente.");
}

try {
    // 1. Rimuoviamo eventuali blocchi di codice Markdown (```json o ```)
    // Usiamo una Regex per estrarre tutto ciò che sta tra le parentesi graffe più esterne
    const jsonMatch = rawOutput.match(/\{[\s\S]*\}/);

    if (!jsonMatch) {
        throw new Error("Non è stato possibile trovare un oggetto JSON valido nell'output.");
    }

    // 2. Parsiamo la stringa pulita
    const cleanObject = JSON.parse(jsonMatch[0]);

    // 3. Restituiamo l'oggetto in modo che n8n lo tratti come JSON nativo
    // Se l'oggetto originale ha già una chiave "output", la restituiamo direttamente
    return cleanObject.output ? cleanObject.output : cleanObject;

} catch (error) {
    // In caso di errore nel parsing, restituiamo l'errore per il debug
    return {
        error: "Errore durante la pulizia del JSON",
        message: error,
        original_text: rawOutput
    };
}

